import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import ItemList from 'flarum/common/utils/ItemList';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
import { RESOURCE, trans } from '../config';
import CampaignModal from './CampaignModal';
import AdvertiserModal from './AdvertiserModal';
import CreativeModal from './CreativeModal';
import ReportSection from './ReportSection';
import SlotSettings from './SlotSettings';

/**
 * Where advertising is managed.
 *
 * A custom page rather than a settings list, because campaigns are records
 * rather than settings — and because putting them in the settings table would
 * bounce every queue worker on the forum each time one was saved.
 */
export default class PlacementPage extends ExtensionPage {
  campaigns = null;
  advertisers = null;
  expanded = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.load();
  }
  load() {
    app.store.find(RESOURCE.campaigns, {
      include: 'advertiser,creatives'
    }).then(campaigns => {
      this.campaigns = campaigns;
      m.redraw();
    });
  }
  content() {
    return m("div", {
      className: "ExtensionPage-body"
    }, this.sections().toArray());
  }
  sections() {
    const items = new ItemList();
    items.add('demo', this.demoSection(), 100);
    items.add('campaigns', this.campaignSection(), 90);
    items.add('reports', m(ReportSection, null), 85);
    items.add('advertisers', this.advertiserSection(), 82);
    items.add('slots', this.slotSection(), 80);
    items.add('settings', this.settingsSection(), 70);
    return items;
  }

  /**
   * The first thing on the page, because it answers the two questions this
   * extension will otherwise be asked forever: where are the slots, and why is
   * my advert not showing.
   */
  demoSection() {
    return m("section", {
      className: "PlacementSection container"
    }, m("h2", null, trans('demo.title')), m("p", {
      className: "helpText"
    }, trans('demo.help')), m(Button, {
      className: "Button",
      icon: "fas fa-eye",
      onclick: () => window.open(`${app.forum.attribute('baseUrl')}/?placement_demo=1`, '_blank', 'noopener')
    }, trans('demo.open')));
  }
  campaignSection() {
    return m("section", {
      className: "PlacementSection container"
    }, m("div", {
      className: "PlacementSection-header"
    }, m("h2", null, trans('campaigns.title')), m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(CampaignModal, {
        onsaved: () => this.load()
      })
    }, trans('campaigns.create'))), this.campaigns === null ? m(LoadingIndicator, null) : this.campaignList());
  }
  campaignList() {
    if (!this.campaigns?.length) {
      return m(Placeholder, {
        text: trans('campaigns.none')
      });
    }
    return m("ul", {
      className: "PlacementList"
    }, this.campaigns.map(campaign => this.campaignRow(campaign)));
  }
  campaignRow(campaign) {
    const id = String(campaign.id());
    const open = this.expanded === id;
    return m("li", {
      className: "PlacementList-item",
      key: id
    }, m("div", {
      className: "PlacementList-row"
    }, m("button", {
      className: "Button Button--link PlacementList-toggle",
      onclick: () => this.expanded = open ? null : id,
      "aria-expanded": open
    }, campaign.name()), this.statusBadge(campaign), m("span", {
      className: "PlacementList-meta"
    }, this.flight(campaign)), m(Button, {
      className: "Button Button--icon Button--link",
      icon: "fas fa-pencil-alt",
      "aria-label": trans('campaigns.edit'),
      onclick: () => app.modal.show(CampaignModal, {
        campaign,
        onsaved: () => this.load()
      })
    }), m(Button, {
      className: "Button Button--icon Button--link",
      icon: "fas fa-trash-alt",
      "aria-label": trans('campaigns.delete'),
      onclick: () => this.remove(campaign)
    })), open && this.creativeList(campaign));
  }

  /**
   * The status an administrator set, and — when they disagree — the fact that
   * the campaign is not actually running.
   *
   * They part ways whenever a flight has ended or a cap has been reached, and
   * that gap is exactly what somebody staring at a campaign marked "active"
   * needs told.
   */
  statusBadge(campaign) {
    const live = campaign.isLive();
    const status = campaign.status();
    return m("span", {
      className: `PlacementBadge PlacementBadge--${live ? 'live' : 'idle'}`
    }, trans(`campaigns.statuses.${status}`), !live && status === 'active' && m("span", {
      className: "PlacementBadge-note"
    }, trans('campaigns.not_running')));
  }
  flight(campaign) {
    const starts = campaign.startsAt();
    const ends = campaign.endsAt();
    if (!starts && !ends) return trans('campaigns.always');
    return [starts ? humanTime(starts) : '…', ' – ', ends ? humanTime(ends) : '…'];
  }
  creativeList(campaign) {
    const creatives = campaign.creatives();
    return m("div", {
      className: "PlacementList-detail"
    }, m("div", {
      className: "PlacementSection-header"
    }, m("h3", null, trans('creatives.title')), m(Button, {
      className: "Button Button--link",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(CreativeModal, {
        campaign,
        onsaved: () => this.load()
      })
    }, trans('creatives.create'))), !creatives || !creatives.length ? m(Placeholder, {
      text: trans('creatives.none')
    }) : m("ul", {
      className: "PlacementList PlacementList--nested"
    }, creatives.map(creative => m("li", {
      className: "PlacementList-item",
      key: creative.id()
    }, m("div", {
      className: "PlacementList-row"
    }, m("span", {
      className: "PlacementList-name"
    }, creative.name()), m("code", {
      className: "PlacementList-type"
    }, creative.type()), m("span", {
      className: "PlacementList-meta"
    }, Object.keys(creative.placements() ?? {}).length || trans('creatives.unassigned')), m(Button, {
      className: "Button Button--icon Button--link",
      icon: "fas fa-pencil-alt",
      "aria-label": trans('creatives.edit'),
      onclick: () => app.modal.show(CreativeModal, {
        campaign,
        creative,
        onsaved: () => this.load()
      })
    }))))));
  }

  /**
   * Who campaigns are reported to.
   *
   * Optional throughout: a forum running only its own house adverts never
   * opens this list.
   */
  advertiserSection() {
    return m("section", {
      className: "PlacementSection container"
    }, m("div", {
      className: "PlacementSection-header"
    }, m("h2", null, trans('advertisers.title')), m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(AdvertiserModal, {
        onsaved: () => this.load()
      })
    }, trans('advertisers.create'))), m("p", {
      className: "helpText"
    }, trans('advertisers.help')), !this.advertisers?.length ? m(Placeholder, {
      text: trans('advertisers.none')
    }) : m("ul", {
      className: "PlacementList"
    }, this.advertisers.map(advertiser => m("li", {
      className: "PlacementList-item",
      key: advertiser.id()
    }, m("div", {
      className: "PlacementList-row"
    }, m("span", {
      className: "PlacementList-name"
    }, advertiser.name()), advertiser.hasReportToken() && m("span", {
      className: "PlacementBadge PlacementBadge--live"
    }, trans('advertisers.has_link')), m("span", {
      className: "PlacementList-meta"
    }, advertiser.contactEmail()), m(Button, {
      className: "Button Button--icon Button--link",
      icon: "fas fa-pencil-alt",
      "aria-label": trans('advertisers.edit'),
      onclick: () => app.modal.show(AdvertiserModal, {
        advertiser,
        onsaved: () => this.load()
      })
    }))))));
  }

  /**
   * Every slot this forum has, and what may be changed about each one.
   */
  slotSection() {
    return m("section", {
      className: "PlacementSection container"
    }, m("h2", null, trans('slots.title')), m("p", {
      className: "helpText"
    }, trans('slots.help')), m(SlotSettings, null));
  }

  /**
   * The two things that really are settings. Everything else is a record.
   */
  settingsSection() {
    return m("section", {
      className: "PlacementSection container"
    }, m("h2", null, trans('settings.title')), m("div", {
      className: "Form-group"
    }, m("label", null, trans('settings.timezone')), m("input", {
      className: "FormControl",
      bidi: this.setting('datlechin-placement.timezone', 'UTC'),
      placeholder: "UTC"
    }), m("div", {
      className: "helpText"
    }, trans('settings.timezone_help'))), m("div", {
      className: "Form-group"
    }, m("label", null, trans('settings.retention_days')), m("input", {
      className: "FormControl",
      type: "number",
      min: "1",
      max: "730",
      bidi: this.setting('datlechin-placement.retention_days', '90')
    }), m("div", {
      className: "helpText"
    }, trans('settings.retention_days_help'))), m("div", {
      className: "Form-group"
    }, m("label", null, trans('settings.ads_txt')), m("textarea", {
      className: "FormControl",
      rows: "5",
      bidi: this.setting('datlechin-placement.ads_txt', ''),
      placeholder: "google.com, pub-0000000000000000, DIRECT, f08c47fec0942fa0"
    }), m("div", {
      className: "helpText"
    }, trans('settings.ads_txt_help'))), m("div", {
      className: "Form-group"
    }, m("label", null, trans('settings.network_scripts')), m("textarea", {
      className: "FormControl",
      rows: "3",
      bidi: this.setting('datlechin-placement.network_scripts', ''),
      placeholder: "https://\u2026/loader.js"
    }), m("div", {
      className: "helpText"
    }, trans('settings.network_scripts_help'))), this.submitButton());
  }
  remove(campaign) {
    if (!confirm(extractText(trans('campaigns.delete_confirm')))) return;
    campaign.delete().then(() => this.load());
  }
}
flarum.reg.add('datlechin-placement', 'admin/components/PlacementPage', PlacementPage);